pub fn __DSP_insert_task<'a>(ctx: &'a Ctx, task: STRUCT_DSP_TASK<'a>) {
    let mut task = task;
    let mut temp: STRUCT_DSP_TASK<'a> = null(ctx);
    if Handle::is_null(fns::__DSP_first_task(ctx).get()) {
        fns::__DSP_curr_task(ctx).set(task);
        fns::__DSP_first_task(ctx).set({
            let __t1 = task;
            fns::__DSP_last_task(ctx).set(__t1);
            __t1
        });
        (task).set_next({
            let __t2 = null::<STRUCT_DSP_TASK<'a>>(ctx);
            (task).set_prev(__t2);
            __t2
        });
        return;
    }
    temp = fns::__DSP_first_task(ctx).get();
    'l1: while !Handle::is_null(temp) {
        'c2: {
            if {
                let __t3 = (temp).priority();
                (task).priority() < __t3
            } {
                (task).set_prev((temp).prev());
                (temp).set_prev(task);
                (task).set_next(temp);
                if Handle::is_null((task).prev()) {
                    fns::__DSP_first_task(ctx).set(task);
                } else {
                    ((task).prev()).set_next(task);
                }
                break 'l1;
            }
            temp = (temp).next();
        }
    }
    if Handle::is_null(temp) {
        (fns::__DSP_last_task(ctx).get()).set_next(task);
        (task).set_next(null::<STRUCT_DSP_TASK<'a>>(ctx));
        (task).set_prev(fns::__DSP_last_task(ctx).get());
        fns::__DSP_last_task(ctx).set(task);
    }
}

pub fn __DSP_remove_task<'a>(ctx: &'a Ctx, task: STRUCT_DSP_TASK<'a>) {
    let mut task = task;
    (task).set_flags((0_i32 as u32));
    (task).set_state((3_i32 as u32));
    if Handle::addr(fns::__DSP_first_task(ctx).get()) == Handle::addr(task) {
        if !Handle::is_null((task).next()) {
            fns::__DSP_first_task(ctx).set((task).next());
            ((task).next()).set_prev(null::<STRUCT_DSP_TASK<'a>>(ctx));
        } else {
            fns::__DSP_first_task(ctx).set({
                let __t2 = {
                    let __t1 = null::<STRUCT_DSP_TASK<'a>>(ctx);
                    fns::__DSP_curr_task(ctx).set(__t1);
                    __t1
                };
                fns::__DSP_last_task(ctx).set(__t2);
                __t2
            });
        }
        return;
    }
    if Handle::addr(fns::__DSP_last_task(ctx).get()) == Handle::addr(task) {
        fns::__DSP_last_task(ctx).set((task).prev());
        ((task).prev()).set_next(null::<STRUCT_DSP_TASK<'a>>(ctx));
        fns::__DSP_curr_task(ctx).set(fns::__DSP_first_task(ctx).get());
        return;
    }
    fns::__DSP_curr_task(ctx).set((task).next());
    ((task).prev()).set_next((task).next());
    ((task).next()).set_prev((task).prev());
}

/// Registers this unit's ports.
pub fn register(ctx: &Ctx) {
    ctx.register_port(0x8033625c, asm___DSPHandler, Returns::Nothing);
    ctx.register_port(
        0x80336680,
        |ctx| {
            let (a0, a1): (STRUCT_DSP_TASK<'_>, STRUCT_DSP_TASK<'_>) = Args::take_all(ctx);
            Ret::put(__DSP_exec_task(ctx, a0, a1), ctx);
        },
        Returns::Nothing,
    );
    ctx.register_port(
        0x80336820,
        |ctx| {
            let (a0,): (STRUCT_DSP_TASK<'_>,) = Args::take_all(ctx);
            Ret::put(__DSP_boot_task(ctx, a0), ctx);
        },
        Returns::Nothing,
    );
    ctx.register_port(
        0x803369ac,
        |ctx| {
            let (a0,): (STRUCT_DSP_TASK<'_>,) = Args::take_all(ctx);
            Ret::put(__DSP_insert_task(ctx, a0), ctx);
        },
        Returns::Nothing,
    );
    ctx.register_port(
        0x80336a4c,
        |ctx| {
            let (a0,): (STRUCT_DSP_TASK<'_>,) = Args::take_all(ctx);
            Ret::put(__DSP_remove_task(ctx, a0), ctx);
        },
        Returns::Nothing,
    );
}
